operations.text:
query Fixture(
  $page: Int
) {
  characters(page: $page) {
    info {
      count
      pages
      next
      prev
    }
    results {
      id
      name
      status
      species
      type
      gender
      image
      created
      origin {
        id
        name
        type
        dimension
        created
      }
      location {
        id
        name
        type
        dimension
        created
      }
      episode {
        id
        name
        air_date
        episode
        created
        characters {
          id
          name
          image
        }
      }
    }
  }
}

query TestEpisodesQuery(
  $id: ID!
) {
  character(id: $id) {
    episode {
      id
      name
    }
    id
  }
}

query TestFreshCharacter(
  $id: ID!
) {
  character(id: $id) {
    id
    name
  }
}

query TestHeaderQuery(
  $id: ID!
) {
  character(id: $id) {
    ...TestHeader_character
    id
  }
}

fragment TestHeader_character on Character {
  name
  status
  species
  image
  origin {
    name
    id
  }
}

query TestList(
  $page: Int
) {
  characters(page: $page) {
    results {
      ...TestRow_character
      ...TestHeader_character
      id
    }
  }
}

fragment TestHeader_character on Character {
  name
  status
  species
  image
  origin {
    name
    id
  }
}

fragment TestRow_character on Character {
  name
  status
  image
}

query TestQualifiedQuery(
  $id: ID!
) {
  character(id: $id) {
    id
    name
  }
}
